 private long foodId(SQLiteDatabase d,String name){Cursor c=d.rawQuery("select id from foods where lower(name)=lower(?) limit 1",new String[]{name});long id=c.moveToFirst()?c.getLong(0):0;c.close();return id;}
 private int countRecipeItems(SQLiteDatabase d,long rid){Cursor c=d.rawQuery("select count(*) from recipe_items where recipe_id=?",new String[]{""+rid});c.moveToFirst();int n=c.getInt(0);c.close();return n;}
 private void insertRecipeItems(SQLiteDatabase d,long rid,Object[][] items){for(Object[] it:items){long fid=foodId(d,(String)it[0]);if(fid>0){ContentValues v=new ContentValues();v.put("recipe_id",rid);v.put("food_id",fid);v.put("grams",((Number)it[1]).doubleValue());d.insert("recipe_items",null,v);}}}
 private void seedRecipe(SQLiteDatabase d,String name,String cat,int portions,Object[][] items){Cursor q=d.rawQuery("select id,user_modified from recipes where lower(name)=lower(?)",new String[]{name});if(q.moveToFirst()){long id=q.getLong(0);int mod=q.getInt(1);q.close();if(mod==0&&countRecipeItems(d,id)==0)insertRecipeItems(d,id,items);if(mod==0)recalcRecipe(d,id);return;}q.close();ContentValues v=new ContentValues();v.put("name",name);v.put("categories",cat);v.put("portions",portions);v.put("builtin",1);v.put("user_modified",0);long id=d.insert("recipes",null,v);insertRecipeItems(d,id,items);recalcRecipe(d,id);}
