 private double gd(Cursor c,String s){int i=c.getColumnIndex(s);return i<0||c.isNull(i)?0:c.getDouble(i);} private int gi(Cursor c,String s){int i=c.getColumnIndex(s);return i<0||c.isNull(i)?0:c.getInt(i);} private String gs(Cursor c,String s){int i=c.getColumnIndex(s);return i<0||c.isNull(i)?"":c.getString(i);}
 public List<Profile> profiles(){ArrayList<Profile>a=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("select * from profiles order by id",null);while(c.moveToNext())a.add(new Profile(c.getLong(c.getColumnIndexOrThrow("id")),gs(c,"name"),gi(c,"age"),gd(c,"target_weight"),gd(c,"cal"),gd(c,"protein"),gd(c,"fat"),gd(c,"carbs"),gd(c,"fiber"),gd(c,"sugar")));c.close();return a;}
 public long saveProfile(Profile p){ContentValues v=new ContentValues();v.put("name",p.name);v.put("age",p.age);v.put("target_weight",p.targetWeight);v.put("cal",p.cal);v.put("protein",p.protein);v.put("fat",p.fat);v.put("carbs",p.carbs);v.put("fiber",p.fiber);v.put("sugar",p.sugar);if(p.id==0)return getWritableDatabase().insert("profiles",null,v);getWritableDatabase().update("profiles",v,"id=?",new String[]{""+p.id});return p.id;}
 private Food foodFrom(Cursor c){Food f=new Food();f.id=c.getLong(c.getColumnIndexOrThrow("id"));f.name=gs(c,"name");f.brand=gs(c,"brand");f.categories=gs(c,"categories");f.basisUnit=gs(c,"basis_unit");f.defaultUnit=gs(c,"default_unit");f.servingBase=gd(c,"serving_base");f.servingLabel=gs(c,"serving_label");f.cal=gd(c,"cal");f.protein=gd(c,"protein");f.fat=gd(c,"fat");f.carbs=gd(c,"carbs");f.fiber=gd(c,"fiber");f.sugar=gd(c,"sugar");f.builtin=gi(c,"builtin");f.userModified=gi(c,"user_modified");return f;}
 public Food food(long id){Cursor c=getReadableDatabase().rawQuery("select * from foods where id=?",new String[]{""+id});Food f=c.moveToFirst()?foodFrom(c):null;c.close();return f;} public Food foodByName(String name){Cursor c=getReadableDatabase().rawQuery("select * from foods where lower(name)=lower(?) limit 1",new String[]{name});Food f=c.moveToFirst()?foodFrom(c):null;c.close();return f;}
 public List<Food> foods(){return foodsFiltered("","");}
 public List<Food> foodsFiltered(String q,String cat){ArrayList<Food>a=new ArrayList<>();String sql="select * from foods where 1=1";ArrayList<String> args=new ArrayList<>();q=q==null?"":q.trim();cat=cat==null?"":cat.trim();if(!q.isEmpty())for(String w:q.split("\\s+")){sql+=" and (lower(name) like ? or lower(categories) like ?)";String x="%"+w.toLowerCase(Locale.ROOT)+"%";args.add(x);args.add(x);}if(!cat.isEmpty()&&!cat.equals("Toutes")&&!cat.equals("Recettes")){sql+=" and lower(categories) like ?";args.add("%"+cat.toLowerCase(Locale.ROOT)+"%");}sql+=" order by name collate nocase";Cursor c=getReadableDatabase().rawQuery(sql,args.toArray(new String[0]));while(c.moveToNext())a.add(foodFrom(c));c.close();return a;}
 public long saveFood(Food f,boolean modified){ContentValues v=foodValues(f.name,f.brand,f.categories,f.basisUnit,f.defaultUnit,f.servingBase,f.servingLabel,f.cal,f.protein,f.fat,f.carbs,f.fiber,f.sugar,f.builtin,modified?1:f.userModified);if(f.id==0){v.put("builtin",0);v.put("user_modified",1);return getWritableDatabase().insert("foods",null,v);}getWritableDatabase().update("foods",v,"id=?",new String[]{""+f.id});return f.id;} public void deleteFood(long id){getWritableDatabase().delete("foods","id=?",new String[]{""+id});}
 public Nutrients forServing(Food f){return new Nutrients(f.cal,f.protein,f.fat,f.carbs,f.fiber,f.sugar).scale(f.servingBase/100.0);} public Nutrients nutrientsFor(Food f,double qty,String unit){double factor;if("portion".equals(unit)||"càc".equals(unit))factor=qty*f.servingBase/100.0;else if("cL".equals(unit))factor=qty*10.0/100.0;else factor=qty/100.0;return new Nutrients(f.cal,f.protein,f.fat,f.carbs,f.fiber,f.sugar).scale(factor);}
 public List<String> categories(){TreeSet<String>s=new TreeSet<>(String.CASE_INSENSITIVE_ORDER);for(Food f:foods())for(String c:f.categories.split(","))if(!c.trim().isEmpty())s.add(c.trim());ArrayList<String>a=new ArrayList<>();a.add("Toutes");a.add("Recettes");a.addAll(s);return a;}
 private Recipe recipeFrom(Cursor c){Recipe r=new Recipe();r.id=c.getLong(c.getColumnIndexOrThrow("id"));r.name=gs(c,"name");r.categories=gs(c,"categories");r.portions=gd(c,"portions");r.cal=gd(c,"cal");r.protein=gd(c,"protein");r.fat=gd(c,"fat");r.carbs=gd(c,"carbs");r.fiber=gd(c,"fiber");r.sugar=gd(c,"sugar");r.builtin=gi(c,"builtin");r.userModified=gi(c,"user_modified");return r;}
 public List<Recipe> recipes(){return recipesFiltered("");} public List<Recipe> recipesFiltered(String q){ArrayList<Recipe>a=new ArrayList<>();q=q==null?"":q.trim();Cursor c=q.isEmpty()?getReadableDatabase().rawQuery("select * from recipes order by name collate nocase",null):getReadableDatabase().rawQuery("select * from recipes where lower(name) like ? or lower(categories) like ? order by name collate nocase",new String[]{"%"+q.toLowerCase(Locale.ROOT)+"%","%"+q.toLowerCase(Locale.ROOT)+"%"});while(c.moveToNext())a.add(recipeFrom(c));c.close();return a;}
 public Recipe recipe(long id){Cursor c=getReadableDatabase().rawQuery("select * from recipes where id=?",new String[]{""+id});Recipe r=c.moveToFirst()?recipeFrom(c):null;c.close();return r;}
 public List<Ingredient> recipeIngredients(long rid){ArrayList<Ingredient>a=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("select ri.id,ri.food_id,ri.grams,f.name from recipe_items ri join foods f on f.id=ri.food_id where ri.recipe_id=? order by ri.id",new String[]{""+rid});while(c.moveToNext()){Ingredient i=new Ingredient();i.id=c.getLong(0);i.foodId=c.getLong(1);i.grams=c.getDouble(2);i.foodName=c.getString(3);i.food=food(i.foodId);a.add(i);}c.close();return a;}
 public long saveRecipe(Recipe r,List<Ingredient> items){ContentValues v=new ContentValues();v.put("name",r.name);v.put("categories",r.categories);v.put("portions",Math.max(1,r.portions));v.put("builtin",r.id==0?0:r.builtin);v.put("user_modified",1);SQLiteDatabase d=getWritableDatabase();long id=r.id;if(id==0)id=d.insert("recipes",null,v);else d.update("recipes",v,"id=?",new String[]{""+id});d.delete("recipe_items","recipe_id=?",new String[]{""+id});for(Ingredient i:items){ContentValues iv=new ContentValues();iv.put("recipe_id",id);iv.put("food_id",i.food!=null?i.food.id:i.foodId);iv.put("grams",i.grams);d.insert("recipe_items",null,iv);}recalcRecipe(d,id);return id;} public void deleteRecipe(long id){SQLiteDatabase d=getWritableDatabase();d.delete("recipe_items","recipe_id=?",new String[]{""+id});d.delete("recipes","id=?",new String[]{""+id});}
 private void recalcRecipe(SQLiteDatabase d,long rid){Cursor rc=d.rawQuery("select portions from recipes where id=?",new String[]{""+rid});if(!rc.moveToFirst()){rc.close();return;}double portions=Math.max(1,rc.getDouble(0));rc.close();Cursor c=d.rawQuery("select f.cal,f.protein,f.fat,f.carbs,f.fiber,f.sugar,ri.grams from recipe_items ri join foods f on f.id=ri.food_id where ri.recipe_id=?",new String[]{""+rid});Nutrients n=new Nutrients();while(c.moveToNext())n.add(new Nutrients(c.getDouble(0),c.getDouble(1),c.getDouble(2),c.getDouble(3),c.getDouble(4),c.getDouble(5)).scale(c.getDouble(6)/100));c.close();n=n.scale(1.0/portions);ContentValues v=new ContentValues();v.put("cal",n.cal);v.put("protein",n.protein);v.put("fat",n.fat);v.put("carbs",n.carbs);v.put("fiber",n.fiber);v.put("sugar",n.sugar);d.update("recipes",v,"id=?",new String[]{""+rid});}
 public List<CatalogItem> catalog(String q,String cat,String type){ArrayList<CatalogItem>a=new ArrayList<>();boolean foods=!"Recette".equals(type)&&!"Recettes".equals(cat);boolean recs=!"Aliment".equals(type)&&(cat==null||cat.equals("Toutes")||cat.equals("Recettes"));if(foods)for(Food f:foodsFiltered(q,cat)){CatalogItem x=new CatalogItem();x.food=f;a.add(x);}if(recs)for(Recipe r:recipesFiltered(q)){CatalogItem x=new CatalogItem();x.recipe=r;a.add(x);}Collections.sort(a,(x,y)->x.name().compareToIgnoreCase(y.name()));return a;}
 private ContentValues mealValues(long pid,String date,String time,String meal,String item,String itemType,double quantity,String unit,String amount,Nutrients n){ContentValues v=new ContentValues();v.put("profile_id",pid);v.put("date",date);v.put("time",time);v.put("meal",meal);v.put("item",item);v.put("item_type",itemType);v.put("quantity",quantity);v.put("unit",unit);v.put("amount",amount);v.put("cal",n.cal);v.put("protein",n.protein);v.put("fat",n.fat);v.put("carbs",n.carbs);v.put("fiber",n.fiber);v.put("sugar",n.sugar);return v;}
 public long addMeal(long pid,String date,String time,String meal,String item,String itemType,double quantity,String unit,Nutrients n){String amount=String.format(Locale.FRANCE,"%.1f %s",quantity,unit);return getWritableDatabase().insert("meals",null,mealValues(pid,date,time,meal,item,itemType,quantity,unit,amount,n));} public void updateMeal(long id,long pid,String date,String time,String meal,String item,String itemType,double quantity,String unit,Nutrients n){getWritableDatabase().update("meals",mealValues(pid,date,time,meal,item,itemType,quantity,unit,String.format(Locale.FRANCE,"%.1f %s",quantity,unit),n),"id=?",new String[]{""+id});} public void deleteMeal(long id){getWritableDatabase().delete("meals","id=?",new String[]{""+id});}
 public List<Meal> meals(long pid,String date){ArrayList<Meal>a=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("select * from meals where profile_id=? and date=? order by time,id",new String[]{""+pid,date});while(c.moveToNext()){Meal m=new Meal();m.id=c.getLong(c.getColumnIndexOrThrow("id"));m.date=gs(c,"date");m.time=gs(c,"time");m.meal=gs(c,"meal");m.item=gs(c,"item");m.itemType=gs(c,"item_type");m.quantity=gd(c,"quantity");m.unit=gs(c,"unit");m.amount=gs(c,"amount");m.cal=gd(c,"cal");m.protein=gd(c,"protein");m.fat=gd(c,"fat");m.carbs=gd(c,"carbs");m.fiber=gd(c,"fiber");m.sugar=gd(c,"sugar");a.add(m);}c.close();return a;}
 public Nutrients totals(long pid,String date){Cursor c=getReadableDatabase().rawQuery("select coalesce(sum(cal),0),coalesce(sum(protein),0),coalesce(sum(fat),0),coalesce(sum(carbs),0),coalesce(sum(fiber),0),coalesce(sum(sugar),0) from meals where profile_id=? and date=?",new String[]{""+pid,date});c.moveToFirst();Nutrients n=new Nutrients(c.getDouble(0),c.getDouble(1),c.getDouble(2),c.getDouble(3),c.getDouble(4),c.getDouble(5));c.close();return n;}
 public List<DayStat> stats(long pid,int days){ArrayList<DayStat>a=new ArrayList<>();LocalDate start=LocalDate.now().minusDays(days-1);for(int i=0;i<days;i++){DayStat s=new DayStat();s.date=start.plusDays(i).toString();s.n=totals(pid,s.date);a.add(s);}return a;}
 public List<HourStat> hourlyCumulative(long pid,String date){ArrayList<HourStat>a=new ArrayList<>();Nutrients run=new Nutrients();for(int h=0;h<=24;h++){if(h<24){Cursor c=getReadableDatabase().rawQuery("select coalesce(sum(cal),0),coalesce(sum(protein),0),coalesce(sum(fat),0),coalesce(sum(carbs),0),coalesce(sum(fiber),0),coalesce(sum(sugar),0) from meals where profile_id=? and date=? and cast(substr(time,1,2) as integer)=?",new String[]{""+pid,date,""+h});c.moveToFirst();run.add(new Nutrients(c.getDouble(0),c.getDouble(1),c.getDouble(2),c.getDouble(3),c.getDouble(4),c.getDouble(5)));c.close();}HourStat s=new HourStat();s.hour=h;s.n=new Nutrients(run.cal,run.protein,run.fat,run.carbs,run.fiber,run.sugar);a.add(s);}return a;}
 public long saveWeight(long pid,String date,double w){ContentValues v=new ContentValues();v.put("profile_id",pid);v.put("date",date);v.put("weight",w);return getWritableDatabase().insert("weights",null,v);} public void updateWeight(long id,String date,double w){ContentValues v=new ContentValues();v.put("date",date);v.put("weight",w);getWritableDatabase().update("weights",v,"id=?",new String[]{""+id});} public void deleteWeight(long id){getWritableDatabase().delete("weights","id=?",new String[]{""+id});}
 public List<WeightLog> weights(long pid){ArrayList<WeightLog>a=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("select id,date,weight from weights where profile_id=? order by date",new String[]{""+pid});while(c.moveToNext()){WeightLog w=new WeightLog();w.id=c.getLong(0);w.date=c.getString(1);w.weight=c.getDouble(2);a.add(w);}c.close();return a;} public List<WeightLog> weightsSince(long pid,LocalDate since){ArrayList<WeightLog>a=new ArrayList<>();for(WeightLog w:weights(pid))if(since==null||!LocalDate.parse(w.date).isBefore(since))a.add(w);return a;}
 public JSONObject exportProfile(long pid)throws JSONException{Profile p=null;for(Profile x:profiles())if(x.id==pid)p=x;if(p==null)throw new JSONException("Profil introuvable");JSONObject root=new JSONObject();root.put("format","nutristat-profile");root.put("version",1);JSONObject po=new JSONObject();po.put("name",p.name);po.put("age",p.age);po.put("targetWeight",p.targetWeight);po.put("cal",p.cal);po.put("protein",p.protein);po.put("fat",p.fat);po.put("carbs",p.carbs);po.put("fiber",p.fiber);po.put("sugar",p.sugar);root.put("profile",po);JSONArray ma=new JSONArray();Cursor mc=getReadableDatabase().rawQuery("select * from meals where profile_id=? order by date,time,id",new String[]{""+pid});while(mc.moveToNext()){JSONObject o=new JSONObject();for(String k:new String[]{"date","time","meal","item","item_type","unit","amount"})o.put(k,gs(mc,k));for(String k:new String[]{"quantity","cal","protein","fat","carbs","fiber","sugar"})o.put(k,gd(mc,k));ma.put(o);}mc.close();root.put("meals",ma);JSONArray wa=new JSONArray();for(WeightLog w:weights(pid)){JSONObject o=new JSONObject();o.put("date",w.date);o.put("weight",w.weight);wa.put(o);}root.put("weights",wa);JSONArray fa=new JSONArray();Cursor fc=getReadableDatabase().rawQuery("select * from foods where builtin=0 or user_modified=1 order by name",null);while(fc.moveToNext()){Food f=foodFrom(fc);JSONObject o=new JSONObject();o.put("name",f.name);o.put("brand",f.brand);o.put("categories",f.categories);o.put("basisUnit",f.basisUnit);o.put("defaultUnit",f.defaultUnit);o.put("servingBase",f.servingBase);o.put("servingLabel",f.servingLabel);o.put("cal",f.cal);o.put("protein",f.protein);o.put("fat",f.fat);o.put("carbs",f.carbs);o.put("fiber",f.fiber);o.put("sugar",f.sugar);fa.put(o);}fc.close();root.put("foods",fa);JSONArray ra=new JSONArray();Cursor rc=getReadableDatabase().rawQuery("select * from recipes where builtin=0 or user_modified=1 order by name",null);while(rc.moveToNext()){Recipe r=recipeFrom(rc);JSONObject o=new JSONObject();o.put("name",r.name);o.put("categories",r.categories);o.put("portions",r.portions);JSONArray ia=new JSONArray();for(Ingredient i:recipeIngredients(r.id)){JSONObject io=new JSONObject();io.put("food",i.foodName);io.put("grams",i.grams);ia.put(io);}o.put("ingredients",ia);ra.put(o);}rc.close();root.put("recipes",ra);return root;}
 public void importProfile(long pid,JSONObject root)throws JSONException{if(!"nutristat-profile".equals(root.optString("format")))throw new JSONException("Fichier Nutristat invalide");SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{JSONObject po=root.getJSONObject("profile");saveProfile(new Profile(pid,po.optString("name","Utilisateur"),po.optInt("age",30),po.optDouble("targetWeight",70),po.optDouble("cal",2000),po.optDouble("protein",120),po.optDouble("fat",70),po.optDouble("carbs",230),po.optDouble("fiber",30),po.optDouble("sugar",50)));JSONArray fa=root.optJSONArray("foods");if(fa!=null)for(int j=0;j<fa.length();j++){JSONObject o=fa.getJSONObject(j);Food f=foodByName(o.getString("name"));if(f==null){f=new Food();f.id=0;f.builtin=0;}f.name=o.getString("name");f.brand=o.optString("brand","");f.categories=o.optString("categories","");f.basisUnit=o.optString("basisUnit","g");f.defaultUnit=o.optString("defaultUnit","g");f.servingBase=o.optDouble("servingBase",100);f.servingLabel=o.optString("servingLabel","");f.cal=o.optDouble("cal",0);f.protein=o.optDouble("protein",0);f.fat=o.optDouble("fat",0);f.carbs=o.optDouble("carbs",0);f.fiber=o.optDouble("fiber",0);f.sugar=o.optDouble("sugar",0);saveFood(f,true);}JSONArray ra=root.optJSONArray("recipes");if(ra!=null)for(int j=0;j<ra.length();j++){JSONObject o=ra.getJSONObject(j);Recipe r=null;for(Recipe x:recipes())if(x.name.equalsIgnoreCase(o.getString("name")))r=x;if(r==null){r=new Recipe();r.id=0;r.builtin=0;}r.name=o.getString("name");r.categories=o.optString("categories","Plats");r.portions=o.optDouble("portions",1);ArrayList<Ingredient> its=new ArrayList<>();JSONArray ia=o.optJSONArray("ingredients");if(ia!=null)for(int k=0;k<ia.length();k++){JSONObject io=ia.getJSONObject(k);Food f=foodByName(io.getString("food"));if(f!=null){Ingredient i=new Ingredient();i.food=f;i.foodId=f.id;i.foodName=f.name;i.grams=io.optDouble("grams",0);its.add(i);}}saveRecipe(r,its);}d.delete("meals","profile_id=?",new String[]{""+pid});d.delete("weights","profile_id=?",new String[]{""+pid});JSONArray ma=root.optJSONArray("meals");if(ma!=null)for(int j=0;j<ma.length();j++){JSONObject o=ma.getJSONObject(j);Nutrients nn=new Nutrients(o.optDouble("cal"),o.optDouble("protein"),o.optDouble("fat"),o.optDouble("carbs"),o.optDouble("fiber"),o.optDouble("sugar"));addMeal(pid,o.optString("date"),o.optString("time","12:00"),o.optString("meal"),o.optString("item"),o.optString("item_type","food"),o.optDouble("quantity",0),o.optString("unit","g"),nn);}JSONArray wa=root.optJSONArray("weights");if(wa!=null)for(int j=0;j<wa.length();j++){JSONObject o=wa.getJSONObject(j);saveWeight(pid,o.optString("date"),o.optDouble("weight"));}d.setTransactionSuccessful();}finally{d.endTransaction();}}
